PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0:  // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        END_IF;
        MotorUp := FALSE;
        MotorDown := FALSE;

    1:  // Moving-up
        IF Not DoorClosed OR AtTop THEN
            State := AtTop ? 2 : 0;
        END_IF;
        MotorUp := DoorClosed AND Not AtTop;
        MotorDown := FALSE;

    2:  // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        END_IF;
        MotorUp := FALSE;
        MotorDown := FALSE;

    3:  // Moving-down
        IF Not DoorClosed OR AtBottom THEN
            State := AtBottom ? 0 : 2;
        END_IF;
        MotorUp := FALSE;
        MotorDown := DoorClosed AND Not AtBottom;

END_CASE;

END_PROGRAM

