PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR

CASE State OF
    0:  // Off
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1:  // Star
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF T#3s >= PT_STAR THEN
            State := 2;
        END_IF;

    2:  // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE

END_PROGRAM

