PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR
VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    OPENING : INT := 1;
    CLOSING : INT := 2;
END_VAR

CASE State OF
    IDLE:
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := CLOSING;
        ELSIF OpenCmd AND NOT OpenLimit THEN
            State := OPENING;
        END_IF;

    OPENING:
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            State := IDLE;
        END_IF;

    CLOSING:
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            State := IDLE;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR
VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0:  // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
        END_IF;

    1:  // Opening
        IF OpenLimit OR Obstruction THEN
            State := 0;
        END_IF;

    2:  // Closing
        IF CloseLimit OR Obstruction THEN
            State := 0;
        END_IF;
END_CASE

CASE State OF
    1:  MotorOpen := TRUE; MotorClose := FALSE;
    2:  MotorOpen := FALSE; MotorClose := TRUE;
    DEFAULT: MotorOpen := FALSE; MotorClose := FALSE;
END_CASE

END_PROGRAM

