IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND T#2s.Timed THEN
    State := 2;
ELSIF State = 2 AND T#2s.Timed THEN
    State := 3;
END_IF;

