    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF State = 1 AND EStop THEN
            State := 2;
        END_IF;
    2:
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF State = 2 AND EStop THEN
            State := 3;
        END_IF;
    3:
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

C1 := State >= 3;
C2 := State >= 2;
C3 := State >= 1;

